test('lineTotal and lineDiscount are used by lineVAT', () => {
  const line = { qty: 100, unitPrice: 500, discountPercent: 10, vatRate: 21 };
  const lt = lineTotal(line);
  const ld = lineDiscount(line);
  const lv = lineVAT(line);

  // lineVAT should use lineTotal and lineDiscount
  const expectedVat = Math.round((lt - ld) * 21 / 100);
  assert.equal(lv, expectedVat);
});

input.new_string:
test('lineTotal and lineDiscount are used by lineVAT', () => {
  const line = { qty: 100, unitPrice: 500, discountPercent: 10, vatRate: 21 };
  const lt = lineTotal(line);
  const ld = lineDiscount(line);
  const lv = lineVAT(line);

  // lineVAT should use lineTotal and lineDiscount
  const expectedVat = Math.round((lt - ld) * 21 / 100);
  assert.equal(lv, expectedVat);
});

test('bulk discount (2.5%) applied for qty >= 10', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  // lineTotal = 10000, no first discount
  // bulk discount = 10000 * 2.5 / 100 = 250
  assert.equal(lineDiscount(line), 250);
});

test('no bulk discount for qty < 10', () => {
  const line = { qty: 9, unitPrice: 1000, vatRate: 21 };
  // No discount without explicit/tier discount
  assert.equal(lineDiscount(line), 0);
});

test('bulk discount with qty exactly 10', () => {
  const line = { qty: 10, unitPrice: 500, vatRate: 21 };
  // lineTotal = 5000, bulk discount = 5000 * 2.5 / 100 = 125
  assert.equal(lineDiscount(line), 125);
});

test('bulk discount with large qty', () => {
  const line = { qty: 1000, unitPrice: 100, vatRate: 21 };
  // lineTotal = 100000, bulk discount = 100000 * 2.5 / 100 = 2500
  assert.equal(lineDiscount(line), 2500);
});

test('bulk discount combined with explicit discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  // lineTotal = 10000
  // first discount = 10000 * 10 / 100 = 1000
  // remaining = 9000
  // bulk discount = 9000 * 2.5 / 100 = 225
  // total = 1000 + 225 = 1225
  assert.equal(lineDiscount(line), 1225);
});

test('bulk discount combined with tier discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 5, vatRate: 21 };
  // lineTotal = 10000
  // first discount = 10000 * 5 / 100 = 500
  // remaining = 9500
  // bulk discount = 9500 * 2.5 / 100 = 237.5 → 238
  // total = 500 + 238 = 738
  assert.equal(lineDiscount(line), 738);
});

test('bulk discount applied to remaining after first discount', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  // lineTotal = 100000
  // first discount = 10000
  // remaining = 90000
  // bulk discount = 90000 * 2.5 / 100 = 2250
  // total = 10000 + 2250 = 12250
  assert.equal(lineDiscount(line), 12250);
});

test('bulk discount never exceeds lineTotal', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  const discount = lineDiscount(line);
  const total = lineTotal(line);
  assert.ok(discount <= total);
});

test('bulk discount is never negative', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  const discount = lineDiscount(line);
  assert.ok(discount >= 0);
});

test('VAT calculated on amount after bulk discount', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  // lineTotal = 10000, bulk discount = 250
  // taxable = 9750, VAT = 9750 * 21 / 100 = 2047.5 → 2048
  const vat = lineVAT(line);
  const expectedVat = Math.round(9750 * 21 / 100);
  assert.equal(vat, expectedVat);
});

test('invoiceTotals includes bulk discount in discount field', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // discount should include bulk discount
  assert.equal(totals.discount, 250);
});

test('invoiceTotals with multiple lines, some with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
      { qty: 5, unitPrice: 1000, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // line 1: bulk discount = 250
  // line 2: no bulk discount
  // total discount = 250
  assert.equal(totals.discount, 250);
});

test('bulk discount with 0% explicit discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  // lineTotal = 10000
  // first discount = 0
  // remaining = 10000
  // bulk discount = 10000 * 2.5 / 100 = 250
  assert.equal(lineDiscount(line), 250);
});

test('bulk discount rounding with fractional amount', () => {
  const line = { qty: 10, unitPrice: 333, vatRate: 21 };
  // lineTotal = 3330, bulk discount = 3330 * 2.5 / 100 = 83.25 → 83
  const discount = lineDiscount(line);
  assert.ok(Number.isInteger(discount));
});

test('invoiceTotals formula with bulk discount: total = subtotal - discount + vat - voucher', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 5, vatRate: 21 },
    ],
    voucher: { code: 'PROMO', amount: 100 },
  };
  const totals = invoiceTotals(invoice);

  // Verify formula
  const expectedTotal = Math.max(
    0,
    totals.subtotal - totals.discount + totals.vat - totals.voucher
  );
  assert.equal(totals.total, expectedTotal);
});

test('bulk discount integration with lineVAT and invoiceTotals', () => {
  const line = { qty: 20, unitPrice: 500, discountPercent: 10, vatRate: 21 };
  const invoice = { lines: [line] };

  // line calculations
  const lt = lineTotal(line);
  const ld = lineDiscount(line);
  const lv = lineVAT(line);
  const totals = invoiceTotals(invoice);

  // Verify invoiceTotals matches line calculations
  assert.equal(totals.subtotal, lt);
  assert.equal(totals.discount, ld);
  assert.equal(totals.vat, lv);
});

test('bulk discount applied at qty 10 boundary', () => {
  const line9 = { qty: 9, unitPrice: 1000, vatRate: 21 };
  const line10 = { qty: 10, unitPrice: 1000, vatRate: 21 };

  const discount9 = lineDiscount(line9);
  const discount10 = lineDiscount(line10);

  assert.equal(discount9, 0);
  assert.equal(discount10, 250);
  assert.ok(discount10 > discount9);
});

test('bulk discount with high quantity', () => {
  const line = { qty: 10000, unitPrice: 100, vatRate: 21 };
  // lineTotal = 1000000, bulk discount = 1000000 * 2.5 / 100 = 25000
  assert.equal(lineDiscount(line), 25000);
});

test('bulk discount with decimal unitPrice results in integer discount', () => {
  // Note: unitPrice should always be integer (cents), but testing rounding
  const line = { qty: 10, unitPrice: 333, vatRate: 21 };
  const discount = lineDiscount(line);
  assert.ok(Number.isInteger(discount));
});

test('bulk discount exclusive - no stacking beyond 2.5%', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  // lineTotal = 100000
  // first discount = 10000
  // remaining = 90000
  // bulk discount = 2250 (2.5% of remaining, not 2.5% of original)
  const discount = lineDiscount(line);
  // total = 12250
  assert.equal(discount, 12250);

  // Verify it's not 12500 (which would be 10% + 2.5% of original)
  assert.notEqual(discount, 12500);
});

test('invoiceTotals with bulk discount on multiple items', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
      { qty: 15, unitPrice: 500, vatRate: 21 },
      { qty: 5, unitPrice: 1000, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  // line 1: bulk = 250
  // line 2: bulk = 375
  // line 3: no bulk
  // total discount should be >= 625
  assert.ok(totals.discount >= 625);
});

