  const totals = invoiceTotals(invoice);
  assert.ok(totals.subtotal >= 0);
  assert.ok(totals.discount >= 0);
  assert.ok(totals.vat >= 0);
  assert.ok(totals.voucher >= 0);
  assert.ok(totals.total >= 0);
});

test('invoiceTotals with large amounts', () => {
  const invoice = {
    lines: [{ qty: 10000, unitPrice: 100000, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1000000000);
  // With qty >= 10, bulk discount applies: 1000000000 * 2.5% = 25000000
  // taxable = 975000000, VAT = 975000000 * 21 / 100 = 204750000
  assert.equal(totals.vat, 204750000);
});

test('invoiceTotals formula: total = subtotal - discount + vat - voucher (clamped)', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 500, discountPercent: 10, vatRate: 21 },
      { qty: 50, unitPrice: 1000, discountPercent: 5, vatRate: 21 },
    ],
    voucher: { code: 'PROMO', amount: 1000 },
  };
  const totals = invoiceTotals(invoice);
  const expectedTotal = Math.max(
    0,
    totals.subtotal - totals.discount + totals.vat - totals.voucher
  );
  assert.equal(totals.total, expectedTotal);
});

test('lineTotal, lineDiscount, lineVAT consistency', () => {
  const line = { qty: 100, unitPrice: 500, discountPercent: 10, vatRate: 21 };
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const vat = lineVAT(line);

  // VAT should be calculated on taxable amount
  const taxableAmount = total - discount;
  const expectedVat = Math.round(taxableAmount * 21 / 100);
  assert.equal(vat, expectedVat);
});

test('invoiceTotals composition: sum of individual amounts', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 500, discountPercent: 10, vatRate: 21 },
      { qty: 50, unitPrice: 1000, discountPercent: 5, vatRate: 21 },
    ],
  };

  const line1Total = lineTotal(invoice.lines[0]);
  const line2Total = lineTotal(invoice.lines[1]);
  const line1Discount = lineDiscount(invoice.lines[0]);
  const line2Discount = lineDiscount(invoice.lines[1]);
  const line1Vat = lineVAT(invoice.lines[0]);
  const line2Vat = lineVAT(invoice.lines[1]);

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, line1Total + line2Total);
  assert.equal(totals.discount, line1Discount + line2Discount);
  assert.equal(totals.vat, line1Vat + line2Vat);
});

test('invoiceTotals empty lines array', () => {
  const invoice = {
    lines: [],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 0);
});

test('lineTotal and lineDiscount are used by lineVAT', () => {
  const line = { qty: 100, unitPrice: 500, discountPercent: 10, vatRate: 21 };
  const lt = lineTotal(line);
  const ld = lineDiscount(line);
  const lv = lineVAT(line);

  // lineVAT should use lineTotal and lineDiscount
  const expectedVat = Math.round((lt - ld) * 21 / 100);
  assert.equal(lv, expectedVat);
});

test('bulk discount (2.5%) applied for qty >= 10', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  // lineTotal = 10000, no first discount
  // bulk discount = 10000 * 2.5 / 100 = 250
  assert.equal(lineDiscount(line), 250);
});

test('no bulk discount for qty < 10', () => {
  const line = { qty: 9, unitPrice: 1000, vatRate: 21 };
  // No discount without explicit/tier discount
  assert.equal(lineDiscount(line), 0);
});

test('bulk discount with qty exactly 10', () => {
  const line = { qty: 10, unitPrice: 500, vatRate: 21 };
  // lineTotal = 5000, bulk discount = 5000 * 2.5 / 100 = 125
  assert.equal(lineDiscount(line), 125);
});

test('bulk discount with large qty', () => {
  const line = { qty: 1000, unitPrice: 100, vatRate: 21 };
  // lineTotal = 100000, bulk discount = 100000 * 2.5 / 100 = 2500
  assert.equal(lineDiscount(line), 2500);
});

test('bulk discount combined with explicit discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  // lineTotal = 10000
  // first discount = 10000 * 10 / 100 = 1000
  // remaining = 9000
  // bulk discount = 9000 * 2.5 / 100 = 225
  // total = 1000 + 225 = 1225
  assert.equal(lineDiscount(line), 1225);
});

test('bulk discount combined with tier discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 5, vatRate: 21 };
  // lineTotal = 10000
  // first discount = 10000 * 5 / 100 = 500
  // remaining = 9500
  // bulk discount = 9500 * 2.5 / 100 = 237.5 → 238
  // total = 500 + 238 = 738
  assert.equal(lineDiscount(line), 738);
});

test('bulk discount applied to remaining after first discount', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  // lineTotal = 100000
  // first discount = 10000
  // remaining = 90000
  // bulk discount = 90000 * 2.5 / 100 = 2250
  // total = 10000 + 2250 = 12250
  assert.equal(lineDiscount(line), 12250);
});

test('bulk discount never exceeds lineTotal', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  const discount = lineDiscount(line);
  const total = lineTotal(line);
  assert.ok(discount <= total);
});

test('bulk discount is never negative', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  const discount = lineDiscount(line);
  assert.ok(discount >= 0);
});

test('VAT calculated on amount after bulk discount', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  // lineTotal = 10000, bulk discount = 250
  // taxable = 9750, VAT = 9750 * 21 / 100 = 2047.5 → 2048
  const vat = lineVAT(line);
  const expectedVat = Math.round(9750 * 21 / 100);
  assert.equal(vat, expectedVat);
});

test('invoiceTotals includes bulk discount in discount field', () => {
