tool_use_result.originalFile:
import { roundCents } from './money.js';

/**
 * Calculate the total for a single invoice line (qty × unitPrice in cents).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single invoice line.
 * Discount includes: explicit/tier discount + 2.5% bulk discount (if qty >= 10, applied after first discount).
 * Bulk discount is applied to the amount remaining after the first discount.
 * Result is rounded to cents and clamped to [0, lineTotal].
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const total = lineTotal(line);

  // Calculate first discount (explicit or tier)
  const firstDiscount = line.discountPercent ? roundCents((total * line.discountPercent) / 100) : 0;
  const remainingAfterFirst = total - firstDiscount;

  // Calculate bulk discount (2.5% if qty >= 10)
  const bulkDiscount = line.qty >= 10 ? roundCents((remainingAfterFirst * 2.5) / 100) : 0;

  const totalDiscount = firstDiscount + bulkDiscount;
  return Math.max(0, Math.min(totalDiscount, total));
}

/**
 * Calculate VAT for a single invoice line.
 * VAT is calculated on (lineTotal - lineDiscount) × vatRate / 100, rounded per line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number}
 */
export function lineVAT(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const taxableAmount = total - discount;
  const vat = (taxableAmount * line.vatRate) / 100;
  return roundCents(vat);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0);
  const voucher = invoice.voucher ? invoice.voucher.amount : 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return {
    subtotal,
    discount,
    vat,
    voucher,
    total,
  };
}

